function initializeMembershipHistory(){let changed=false;for(const c of db.clubs||[])c.members.forEach((m,i)=>{if(!m.id){m.id='CM-'+c.id+'-'+i;m.recordOrigin='Existing demonstration membership';changed=true}});if(changed)save()}
function membershipReviewer(c){return uid===c.mentor||uid==='sa1'||uid==='a1'}
function membershipById(c,id){return c.members.find(m=>m.id===id)}
function membershipExitOpen(c){return ['APPROVED','ACTIVE','RENEWAL_DUE','SUSPENDED'].includes(c.state)}
function membershipExitBlocks(c,student){let blocks=[];if(c.owner===student)blocks.push('Transfer the club lead through the verified handover and renewal workflow.');if(c.leaders.some(l=>l.user===student&&['NOMINATED','ACTIVE'].includes(l.state)))blocks.push('Resolve nominated or active leadership appointments.');for(const plan of c.plans)if(isApprovedClubPlan(plan)&&latestApprovedRevision(c,plan)&&clubItems(plan).some(i=>i.lead===student&&i.status!=='CANCELLED'&&!clubItemActivity(i)))blocks.push('Revise and reapprove unconverted planned activities assigned to this member.');if((c.handovers||[]).some(h=>['SUBMITTED','ACKNOWLEDGED'].includes(h.state)&&[h.incoming,h.outgoing].includes(student)))blocks.push('Complete the pending handover.');return [...new Set(blocks)]}
function clubMembershipPanel(c){let mineRecords=c.members.filter(m=>m.user===uid),canReview=membershipReviewer(c),requests=(c.membershipExits||[]).filter(r=>canReview||r.student===uid);return `<div class="panel" style="margin-top:20px"><h3>Membership periods & exit review</h3><p>Membership ends only after mentor review and Student Affairs authorization. Existing project participation remains governed by each project's Participants tab. A new membership request creates a separate period.</p>${mineRecords.map(m=>`<div class="card"><strong>My membership · ${esc(m.id)}</strong> ${pill(m.state)}<p class="meta">${esc(m.since)}${m.endedAt?' → '+esc(eventTime(m.endedAt)):''} · ${esc(m.recordOrigin||'Recorded application')}${m.approvedAt?' · Approved '+esc(eventTime(m.approvedAt)):''}</p>${m.state==='ACTIVE'&&membershipExitOpen(c)&&!(c.membershipExits||[]).some(r=>r.membershipId===m.id&&['REQUESTED','MENTOR_REVIEWED'].includes(r.state))?btn('Request club exit',`membershipExitForm('${c.id}','${m.id}')`):''}${m.state==='PENDING'?btn('Cancel my application',`membershipApplicationForm('${c.id}','${m.id}','CANCELLED')`):''}</div>`).join('')||'<p>No personal membership records.</p>'}${mineRecords.length?btn('Export my membership history',`exportMembershipHistory('${c.id}')`):''}${canReview||manageClub(c)?`<h4>Pending applications</h4>${c.members.filter(m=>m.state==='PENDING').map(m=>`<div class="row"><span>${esc(name(m.user))} · ${esc(m.id)}</span>${btn('Reject with reason',`membershipApplicationForm('${c.id}','${m.id}','REJECTED')`)}</div>`).join('')||'<p>No pending applications.</p>'}`:''}${requests.map(r=>{let blockers=membershipExitBlocks(c,r.student);return `<div class="card" style="margin-top:12px"><strong>${esc(name(r.student))} · ${esc(r.id)}</strong> ${pill(r.state)}<p>${esc(r.reason)}</p><p class="meta">Requested ${esc(eventTime(r.requestedAt))} · Membership ${esc(r.membershipId)}</p>${blockers.length?`<div class="notice">${blockers.map(esc).join('<br>')}</div>`:''}${r.mentorReason?`<p>Mentor review: ${esc(r.mentorReason)} · ${esc(name(r.reviewedBy))} · ${esc(eventTime(r.reviewedAt))}</p>`:''}${r.decisionReason?`<p>Decision: ${esc(r.decisionReason)} · ${esc(name(r.decidedBy))} · ${esc(eventTime(r.decidedAt))}</p>`:''}<div class="buttons">${uid===c.mentor&&r.student!==uid&&r.state==='REQUESTED'?btn('Review exit request',`membershipExitReviewForm('${c.id}','${r.id}','mentor')`):''}${uid==='sa1'&&r.student!==uid&&r.reviewedBy!==uid&&r.state==='MENTOR_REVIEWED'?btn('Authorize or reject exit',`membershipExitReviewForm('${c.id}','${r.id}','authorize')`):''}${uid===r.student&&['REQUESTED','MENTOR_REVIEWED'].includes(r.state)?btn('Cancel exit request',`membershipExitReviewForm('${c.id}','${r.id}','cancel')`):''}</div></div>`}).join('')}</div>`}
function membershipExitForm(cid,mid){modal(`<h2>Request club exit</h2><form onsubmit="requestMembershipExit(event,'${cid}','${mid}')"><label>Reason and handover references<textarea name="reason" required></textarea></label><p>Your membership remains active until the request is authorized. Existing project participation is retained separately.</p><button class="primary">Submit request</button></form>`)}
function requestMembershipExit(e,cid,mid){e.preventDefault();let c=clubById(cid),m=c&&membershipById(c,mid),reason=new FormData(e.target).get('reason').trim();if(!c||!m||m.user!==uid||m.state!=='ACTIVE'||!membershipExitOpen(c)||!reason)return toast('Own active membership and a reason are required.');c.membershipExits??=[];if(c.membershipExits.some(r=>r.membershipId===mid&&['REQUESTED','MENTOR_REVIEWED'].includes(r.state)))return toast('An exit request is already pending.');c.membershipExits.push({id:clubKey('MX'),membershipId:mid,student:uid,state:'REQUESTED',reason,requestedBy:uid,requestedAt:new Date().toISOString()});clubLog(c,'Membership exit requested by '+name(uid));closeModal();render()}
function membershipExitReviewForm(cid,rid,phase){let c=clubById(cid),r=(c.membershipExits||[]).find(r=>r.id===rid);if(!r)return;modal(`<h2>${phase==='cancel'?'Cancel request':'Review membership exit'}</h2><p>${esc(name(r.student))} · ${esc(r.reason)}</p><form onsubmit="reviewMembershipExit(event,'${cid}','${rid}')"><label>Decision<select name="decision">${(phase==='cancel'?['CANCELLED']:phase==='mentor'?['MENTOR_REVIEWED','REJECTED']:['APPROVED','REJECTED']).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Reason<textarea name="reason" required></textarea></label><button class="primary">Record decision</button></form>`)}
function reviewMembershipExit(e,cid,rid){e.preventDefault();let c=clubById(cid),r=(c?.membershipExits||[]).find(r=>r.id===rid),m=r&&membershipById(c,r.membershipId),f=new FormData(e.target),decision=f.get('decision'),reason=f.get('reason').trim();if(!c||!r||!m||m.state!=='ACTIVE'||!membershipExitOpen(c)||!reason||!['REQUESTED','MENTOR_REVIEWED'].includes(r.state))return toast('A current exit request and reason are required.');let cancel=uid===r.student&&decision==='CANCELLED',mentorReview=uid===c.mentor&&uid!==r.student&&r.state==='REQUESTED'&&['MENTOR_REVIEWED','REJECTED'].includes(decision),authorization=uid==='sa1'&&uid!==r.student&&uid!==r.reviewedBy&&r.state==='MENTOR_REVIEWED'&&['APPROVED','REJECTED'].includes(decision);if(!cancel&&!mentorReview&&!authorization)return toast('Assigned mentor review and independent Student Affairs authorization required.');if(['MENTOR_REVIEWED','APPROVED'].includes(decision)){let blockers=membershipExitBlocks(c,r.student);if(blockers.length)return toast(blockers.join(' '))}let now=new Date().toISOString();r.state=decision;if(decision==='MENTOR_REVIEWED'){r.reviewedBy=uid;r.reviewedAt=now;r.mentorReason=reason}else{r.decidedBy=uid;r.decidedAt=now;r.decisionReason=reason}if(decision==='APPROVED'){m.state='WITHDRAWN';m.endedAt=now;m.exitRequestId=r.id;m.endedBy=uid}clubLog(c,'Membership exit '+decision+' for '+name(r.student));closeModal();render()}
function membershipApplicationForm(cid,mid,decision){modal(`<h2>${decision==='CANCELLED'?'Cancel application':'Reject application'}</h2><form onsubmit="decideMembershipApplication(event,'${cid}','${mid}','${decision}')"><label>Reason<textarea name="reason" required></textarea></label><button class="primary">Record decision</button></form>`)}
function decideMembershipApplication(e,cid,mid,decision){e.preventDefault();let c=clubById(cid),m=c&&membershipById(c,mid),reason=new FormData(e.target).get('reason').trim();if(!c||!m||m.state!=='PENDING'||!['APPROVED','ACTIVE','RENEWAL_DUE'].includes(c.state)||!reason)return;let allowed=decision==='CANCELLED'&&uid===m.user||decision==='REJECTED'&&uid!==m.user&&(manageClub(c)||uid===c.mentor||uid==='sa1');if(!allowed)return;m.state=decision;m.decidedBy=uid;m.decidedAt=new Date().toISOString();m.decisionReason=reason;clubLog(c,'Membership application '+decision+' for '+name(m.user));closeModal();render()}
function endClubAppointmentForm(cid,lid){modal(`<h2>Close leadership appointment record</h2><p>Only a nomination may be cancelled or an expired term recorded complete. Current lead transfers use the verified handover workflow.</p><form onsubmit="endClubAppointment(event,'${cid}','${lid}')"><label>Reason<textarea name="reason" required></textarea></label><button class="primary">Close appointment record</button></form>`)}
function endClubAppointment(e,cid,lid){e.preventDefault();let c=clubById(cid),l=c?.leaders.find(l=>l.id===lid),reason=new FormData(e.target).get('reason').trim();if(!c||!l||uid!==c.mentor||uid===l.user||!reason||!membershipExitOpen(c))return;if(l.state!=='NOMINATED'&&!(l.state==='ACTIVE'&&l.end<localDay()&&l.user!==c.owner))return toast('Use verified handover for current terms and the club lead.');if(l.state==='ACTIVE'&&(c.budgets||[]).some(b=>b.state!=='CLEARED'))return toast('Financial clearance is required before closing an expired appointment.');l.state=l.state==='NOMINATED'?'CANCELLED':'TERM_COMPLETED';l.closedBy=uid;l.closedAt=new Date().toISOString();l.closeReason=reason;clubLog(c,'Leadership record closed for '+name(l.user));closeModal();render()}
function exportMembershipHistory(cid){let c=clubById(cid);if(!c)return;download({demo:true,student:name(uid),club:{id:c.id,title:c.title},membershipPeriods:c.members.filter(m=>m.user===uid),exitRequests:(c.membershipExits||[]).filter(r=>r.student===uid),leadershipHistory:c.leaders.filter(l=>l.user===uid)},'KCC360-my-club-membership-history.json')}
function membershipActionCards(){let rows=db.clubs.flatMap(c=>(c.membershipExits||[]).filter(r=>uid===c.mentor&&r.state==='REQUESTED'||uid==='sa1'&&r.state==='MENTOR_REVIEWED').map(r=>({c,r})));return rows.length?`<div class="panel" style="margin-top:20px"><h2>Club membership exit reviews</h2>${rows.map(({c,r})=>`<div class="row"><span>${esc(c.title)} · ${esc(name(r.student))}</span>${btn('Open club',"go('Clubs')")}</div>`).join('')}</div>`:''}
